set -e
docmgr task add --ticket IRWB-014 --text 'Implement the Typed codec, corpus metadata, notes, and fresh explore script'
docmgr task add --ticket IRWB-014 --text 'Check exact fixtures, generated round trips, pass verdicts, and instruction totals'
docmgr task add --ticket IRWB-014 --text 'Exercise the workbench loader and record implementation evidence'
mkdir -p corpus/projects/lz-roundtrip/scripts
cat > corpus/projects/lz-roundtrip/main.typed <<'EOF'
function hash3(a: i32, b: i32, c: i32): i32 {
    return ((a * 31 + b) * 31 + c) & 15;
}

function compress(input: buffer, packed: buffer, chainLimit: i32): i32 {
    const head = new Int32Array(16);
    const prev = new Int32Array(24);
    const n = input.length;
    let i = 0;
    let k = 0;

    while (i < n) {
        let bestLen = 0;
        let bestDistance = 0;
        if (i + 3 <= n) {
            const bucket = hash3(input.charCodeAt(i), input.charCodeAt(i + 1), input.charCodeAt(i + 2));
            let link = head[bucket];
            let visits = 0;
            while (link !== 0 && visits < chainLimit) {
                const candidate = link - 1;
                let len = 0;
                while (len < 6 && i + len < n) {
                    const current = input.charCodeAt(i + len);
                    const earlier = input.charCodeAt(candidate + len);
                    if (current !== earlier) {
                        break;
                    }
                    len = len + 1;
                }
                if (len > bestLen) {
                    bestLen = len;
                    bestDistance = i - candidate;
                }
                link = prev[candidate];
                visits = visits + 1;
            }
        }

        let advance = 1;
        if (bestLen < 3) {
            packed.setCharCodeAt(k, input.charCodeAt(i));
        } else {
            const token = 128 | ((bestLen - 3) << 5) | (bestDistance - 1);
            packed.setCharCodeAt(k, token);
            advance = bestLen;
        }

        // Insert every consumed position that begins a complete triple.
        for (let p = i; p < i + advance; p = p + 1) {
            if (p + 3 <= n) {
                const bucket = hash3(input.charCodeAt(p), input.charCodeAt(p + 1), input.charCodeAt(p + 2));
                prev[p] = head[bucket];
                head[bucket] = p + 1;
            }
        }
        i = i + advance;
        k = k + 1;
    }
    return k;
}

function decompress(packed: buffer, packedLen: i32, output: buffer): i32 {
    let written = 0;
    for (let k = 0; k < packedLen; k = k + 1) {
        const token = packed.charCodeAt(k);
        if ((token & 128) === 0) {
            output.setCharCodeAt(written, token);
            written = written + 1;
        } else {
            const len = ((token >>> 5) & 3) + 3;
            const distance = (token & 31) + 1;
            // Forward copying lets a match read cells it has just written.
            for (let copied = 0; copied < len; copied = copied + 1) {
                const cell = output.charCodeAt(written - distance);
                output.setCharCodeAt(written, cell);
                written = written + 1;
            }
        }
    }
    return written;
}

function roundTrip(input: buffer, packed: buffer, output: buffer, chainLimit: i32): i32 {
    const packedLen = compress(input, packed, chainLimit);
    return decompress(packed, packedLen, output);
}
EOF
rg -n 'output.charCodeAt' corpus/projects/lz-roundtrip/main.typed
cat > corpus/projects/lz-roundtrip/project.json <<'EOF'
{
  "title": "LZ round trip",
  "about": [
    "Find repeated triples through a hash chain, then decode literals and",
    "overlapping back-references with checked buffer accesses."
  ],
  "group": "Programs",
  "sources": ["main.typed"],
  "pipeline": "speed",
  "ingest": { "tape": true },
  "focus": 74,
  "scripts": {
    "explore": { "about": "Encode and decode 24 A cells and count RV32 instructions.", "fresh": true }
  },
  "inputs": {
    "hash3": { "a": [0, 127], "b": [0, 127], "c": [0, 127] },
    "compress": {
      "input": { "buffer": [0, 24], "cell": [65, 66] },
      "packed": { "buffer": [24, 24], "cell": [0, 0] },
      "chainLimit": [1, 3]
    },
    "decompress": {
      "packed": { "cells": [65, 224, 66, 192, 127] },
      "packedLen": 5,
      "output": { "buffer": [24, 24], "cell": [0, 0] }
    },
    "roundTrip": {
      "input": { "buffer": [0, 24], "cell": [65, 66] },
      "packed": { "buffer": [24, 24], "cell": [0, 0] },
      "output": { "buffer": [24, 24], "cell": [0, 0] },
      "chainLimit": [1, 3]
    }
  }
}
EOF
cat > corpus/projects/lz-roundtrip/scripts/explore.js <<'EOF'
// Encode and decode 24 A cells on a fresh program.
p.pipeline('speed');
const image = p.compile({ chains: true, coalesce: true, homes: true });
const input = Array(24).fill(65);
const scratch = () => Array(24).fill(0);
const encoded = image.run('compress', [input, scratch(), 3]);
const decoded = image.run('roundTrip', [input, scratch(), scratch(), 3]);
return {
  packed: encoded.buffers[1].cells.slice(0, encoded.result),
  decoded: decoded.buffers[2].cells.slice(0, decoded.result),
  instructions: decoded.steps,
};
EOF
cat > corpus/projects/lz-roundtrip/notes.md <<'EOF'
# LZ round trip

The input holds up to 24 seven-bit characters, one per u16 cell. Pass distinct
24-cell buffers for the packed stream and decoded output. The chain limit is
1–3. \`compress\` returns the number of packed cells. Pass that length to
\`decompress\`, which requires a valid stream that expands to at most 24 cells
and returns the number of decoded cells. \`roundTrip\` connects the two calls.

Each packed cell holds one byte.

| Bits | Meaning |
| --- | --- |
| \`0ccccccc\` | Emit the literal character \`c\` (0–127). |
| \`1llddddd\` | Copy \`ll + 3\` cells from \`ddddd + 1\` cells back. |

The compressor visits hash-chain links newest first and keeps the nearest
match on ties. It inserts all consumed positions that begin a complete
triple. The decoder copies forward, so a distance-one match can extend a
run by reading cells from earlier iterations of the same copy loop.

Run this in the workbench console with the project open to encode and decode
24 A cells on a fresh optimized program.

\`\`\`js
wb.projects.current.run('explore');
\`\`\`

The packed prefix is \`[65, 224, 224, 224, 192]\`. The script also returns all
24 decoded cells and the RV32 instruction count for the round trip.

The next console example encodes \`AABBAAB\` with one and two chain visits.

\`\`\`js
const input = [65, 65, 66, 66, 65, 65, 66];
return [1, 2].map(limit => {
  const run = p.exec('compress', [input, Array(24).fill(0), limit]);
  return run.buffers[1].cells.slice(0, run.result);
});
\`\`\`

One visit yields seven literals. Two visits yield \`[65, 65, 66, 66, 131]\`
because the older \`AAB\` matches at distance four after the newer \`BAA\`
collides in the same bucket.
EOF

node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { installVendor } from './tools/node-vendor.mjs';
import { projectAllFiles } from './tools/corpus.mjs';
await installVendor({ reference: true });
const { Program } = await import('./dist/typed/program.js');
const { projectSource } = await import('./dist/typed/project.js');
const { createWb } = await import('./dist/workbench/index.js');
const id = 'lz-roundtrip';
const files = projectAllFiles(id);
const p = Program.fromProject(projectSource(id, files));
assert.equal(p.status, 'ok', p.error?.message);
const a = Array(24).fill(65);
const colliding = [65,65,66,66,65,65,66];
const scratch = () => Array(24).fill(0);
for (const [input, limit, expected] of [[[],3,[]],[[0,127],3,[0,127]],[a,3,[65,224,224,224,192]],[colliding,1,colliding],[colliding,2,[65,65,66,66,131]]]) {
  const run = p.exec('compress', [input, scratch(), limit]);
  assert.equal(run.trap, false);
  assert.equal(run.result, expected.length);
  assert.deepEqual(run.buffers[1].cells.slice(0, run.result), expected);
}
const fixture = p.exec('decompress', [[65,224,66,192,127],5,scratch()]);
assert.equal(fixture.result,14);
assert.deepEqual(fixture.buffers[1].cells.slice(0,14), [...Array(7).fill(65), ...Array(6).fill(66), 127]);
console.log('r0 encoding and decoding fixtures passed');
const wb = createWb({ builtins: [{ id, files }] });
const project = wb.projects.open(id);
console.log(project.program.status, project.run('explore'));
EOF

node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { installVendor } from './tools/node-vendor.mjs';
import { projectAllFiles } from './tools/corpus.mjs';
await installVendor();
const { createWb } = await import('./dist/workbench/index.js');
const id = 'lz-roundtrip';
const wb = createWb({ projects: [{ id, files: projectAllFiles(id) }] });
const project = wb.projects.open(id);
assert.equal(project.program.status, 'ok');
const result = await project.run('explore');
assert.deepEqual(result.packed, [65, 224, 224, 224, 192]);
assert.deepEqual(result.decoded, Array(24).fill(65));
assert.equal(project.program.rev, 'r0');
console.log(result);
EOF

node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { installVendor } from './tools/node-vendor.mjs';
import { projectFiles } from './tools/corpus.mjs';
await installVendor({ reference: true });
const { Program } = await import('./dist/typed/program.js');
const { projectSource } = await import('./dist/typed/project.js');
const { storeOf } = await import('./dist/typed/ir.js');
const { benchCase, readBuffer } = await import('./dist/typed/evaluate.js');
const { imageFromCode, runImage } = await import('./dist/typed/backend/index.js');
const ps = projectSource('lz-roundtrip', projectFiles('lz-roundtrip'));
const p = Program.fromProject(ps);
const { image, entries } = globalThis.typedRv32.compile(ps.source, [], undefined);
const c = benchCase(storeOf(p.head.value), 'roundTrip', { input: { cells: [65,65,65,65] }, packed: { cells: Array(24).fill(0) }, output: { cells: Array(24).fill(0) }, chainLimit: 3 });
const result = runImage(imageFromCode(ps.id, image, entries), c.fn, c.args, c.memory, { limit: 2e5 });
assert.equal(result.trap, false);
assert.equal(result.result, 4);
assert.deepEqual(readBuffer(result.bytes, c.args[2]).slice(0,4), [65,65,65,65]);
console.log('reference image probe passed:', result.steps, 'instructions');
EOF
rg -n 'assert\.(equal|deepEqual).*([0-9]|builtinProjects\(|projectIds\()' tests/workbench/scripts.test.mjs
git ls-files 'corpus/projects/*/scripts/*.js' | wc -l

cat > tests/typed/lz-roundtrip.test.mjs <<'EOF'
import assert from 'node:assert/strict';
import test from 'node:test';
import { projectAllFiles } from '../../tools/corpus.mjs';
import { installVendor } from '../../tools/node-vendor.mjs';

await installVendor({ reference: true });
const { createArtifact } = await import('../../dist/framework/contracts/index.js');
const { imageFromCode, lowerToImage, runImage } = await import('../../dist/typed/backend/index.js');
const { agrees, benchCase, casesFrom, evaluate, readBuffer } = await import('../../dist/typed/evaluate.js');
const { storeOf } = await import('../../dist/typed/ir.js');
const { Program } = await import('../../dist/typed/program.js');
const { projectSource } = await import('../../dist/typed/project.js');
const { BindingsIR } = await import('../../dist/typed/specialize.js');
const { createWb } = await import('../../dist/workbench/index.js');

const id = 'lz-roundtrip';
const files = projectAllFiles(id);
const source = projectSource(id, files);
const backendOptions = { chains: true, coalesce: true, homes: true };
const sample = { count: 100, seed: 7 };
const longMatch = Array(24).fill(65);
const collision = [65, 65, 66, 66, 65, 65, 66];
const longCollision = [...collision, ...collision, ...collision, 65, 65, 66];
const encodedRun = [65, 224, 224, 224, 192];
const scratch = { buffer: [24, 24], cell: [0, 0] };
const codecCase = (store, fn, input, chainLimit) =>
  benchCase(store, fn, { input: { cells: input }, packed: scratch, output: scratch, chainLimit });
const interpret = (store, c) => evaluate(store, c.fn, c.args, c.memory, { limit: 2e4 });
const emulate = (image, c) => runImage(image, c.fn, c.args, c.memory, { limit: 2e5 });

function assertCompletion(run, label) {
  assert.equal(run.limit, false, label);
  assert.equal(run.trap, false, label);
}

function assertPrefix(run, addr, expected, label) {
  assertCompletion(run, label);
  assert.equal(run.result, expected.length, label);
  assert.deepEqual(readBuffer(run.bytes, addr).slice(0, run.result), expected, label);
}

async function checkedSpeed(program, t, label) {
  const { steps } = await program.pipeline(source.meta.pipeline, { count: sample.count });
  assert.deepEqual(steps.filter(s => s.rejected), [], label);
  const changed = steps.filter(s => s.changed);
  assert.ok(changed.length > 0, label);
  const total = sample.count * Object.keys(source.meta.inputs).length;
  for (const step of changed) assert.equal(step.check, \`\${total}/\${total}\`, \`\${label} \${step.pass} \${step.rev}\`);
  t.diagnostic(\`\${label} pass verdicts: \${changed.map(s => \`\${s.rev} \${s.pass} \${s.check}\`).join(', ')}\`);
}

test('LZ exact tokens, byte-for-byte round trips, and checked instruction measurements', async t => {
  const program = Program.fromProject(source);
  assert.equal(program.status, 'ok', program.error?.message);
  const base = storeOf(program.origin.value);
  const r0Image = lowerToImage(program.origin).image;
  const { image, entries } = globalThis.typedRv32.compile(source.source, [], undefined);
  const reference = imageFromCode(id, image, entries);
  await checkedSpeed(program, t, 'general speed');
  const head = storeOf(program.head.value);
  const speedImage = lowerToImage(program.head, backendOptions).image;
  const engines = {
    'r0 evaluator': c => interpret(base, c),
    'r0 RV32': c => emulate(r0Image, c),
    'speed RV32': c => emulate(speedImage, c),
    'reference RV32': c => emulate(reference, c),
  };

  const encodingFixtures = [
    ['empty', [], 3, []],
    ['literal boundaries', [0, 127], 3, [0, 127]],
    ['overlap and nearest tie', longMatch, 3, encodedRun],
    ['collision at limit 1', collision, 1, collision],
    ['collision at limit 2', collision, 2, [65, 65, 66, 66, 131]],
  ];
  const decode = benchCase(base, 'decompress', {
    ...source.meta.inputs.decompress,
    packed: { cells: [65, 224, 66, 192, 127, ...Array(19).fill(127)] },
  });
  const decodedFixture = [...Array(7).fill(65), ...Array(6).fill(66), 127];
  for (const [engine, run] of Object.entries(engines)) {
    for (const [name, input, limit, expected] of encodingFixtures) {
      const c = codecCase(base, 'compress', input, limit);
      assertPrefix(run(c), c.args[1], expected, \`\${engine} \${name}\`);
    }
    assertPrefix(run(decode), decode.args[2], decodedFixture, \`\${engine} standalone decoder\`);
  }

  const generated = fn => casesFrom(base, fn, { ...sample, inputs: source.meta.inputs[fn] });
  const roundTrips = generated('roundTrip');
  let maxBase = 0;
  let maxHead = 0;
  for (const fn of program.fns()) {
    for (const c of fn === 'roundTrip' ? roundTrips : generated(fn)) {
      const label = \`\${fn} seed-\${sample.seed} case \${c.n}\`;
      const expected = interpret(base, c);
      const actual = interpret(head, c);
      assertCompletion(expected, \`r0 \${label}\`);
      assertCompletion(actual, \`speed \${label}\`);
      assert.ok(agrees(expected, actual), label);
      maxBase = Math.max(maxBase, expected.steps);
      maxHead = Math.max(maxHead, actual.steps);
    }
  }
  t.diagnostic(\`Maximum generated evaluator steps: r0 \${maxBase}, speed \${maxHead}\`);
  for (const [name, input] of [['24 A cells', longMatch], ['24 collision-heavy cells', longCollision]]) {
    const c = codecCase(base, 'roundTrip', input, 3);
    const expected = readBuffer(c.memory, c.args[0]);
    const r0 = interpret(base, c);
    const speed = interpret(head, c);
    assertPrefix(r0, c.args[2], expected, \`r0 \${name}\`);
    assertPrefix(speed, c.args[2], expected, \`speed \${name}\`);
    t.diagnostic(\`Evaluator steps for \${name}: r0 \${r0.steps}, speed \${speed.steps}\`);
  }

  const specialized = Program.fromProject(source);
  const bindings = createArtifact(BindingsIR, 'lz-limit', {
    formatVersion: 1,
    source: 'fixed chain limit',
    bindings: ['compress', 'roundTrip'].map(fn => ({
      fn, param: 'chainLimit', value: 3, entity: 'lz/chainLimit',
    })),
  });
  assert.equal((await specialized.specialize(bindings)).changed, true);
  await checkedSpeed(specialized, t, 'specialized speed');
  const specializedImage = lowerToImage(specialized.head, backendOptions).image;

  const totals = { r0: 0, speed: 0, reference: 0 };
  let fixedCases = 0;
  let generalFixed = 0;
  let specializedFixed = 0;
  for (const c of roundTrips) {
    const input = readBuffer(c.memory, c.args[0]);
    const outputAt = c.args[2];
    assertPrefix(engines['r0 evaluator'](c), outputAt, input, \`r0 evaluator case \${c.n}\`);

    for (const [label, img] of [['r0', r0Image], ['speed', speedImage], ['reference', reference]]) {
      const run = emulate(img, c);
      assertPrefix(run, outputAt, input, \`\${label} RV32 case \${c.n}\`);
      totals[label] += run.steps;
      if (label === 'speed' && c.args[3] === 3) generalFixed += run.steps;
    }
    if (c.args[3] === 3) {
      const run = emulate(specializedImage, c);
      assertPrefix(run, outputAt, input, \`specialized speed RV32 case \${c.n}\`);
      fixedCases++;
      specializedFixed += run.steps;
    }
  }
  assert.ok(fixedCases > 0 && fixedCases < roundTrips.length);
  t.diagnostic(\`RV32 instructions over \${roundTrips.length} seed-\${sample.seed} cases: \${JSON.stringify(totals)}\`);
  t.diagnostic(\`RV32 instructions over the same \${fixedCases} cases at limit 3: general \${generalFixed}, specialized \${specializedFixed}\`);
});

test('LZ workbench opens the tape project and runs explore on a fresh program', async () => {
  const wb = createWb({ projects: [{ id, files }] });
  const project = wb.projects.open(id);
  assert.equal(project.program.status, 'ok');
  assert.equal(project.program.rev, 'r0');
  const result = await project.run('explore');
  assert.deepEqual(result.packed, encodedRun);
  assert.deepEqual(result.decoded, longMatch);
  assert.ok(result.instructions > 0);
  assert.equal(project.program.rev, 'r0');
});
EOF
node --test tests/typed/lz-roundtrip.test.mjs
